//&#60;&#33;&#91;CDATA[
if (typeof(COMMON_JS) == 'undefined') {
    // 한번만 실행
    var COMMON_JS = true;
    (function($) {
        /**
         * @method
         * @name external_hover_img
         * @description desc
         * @param {string} data desc
         * @returns
         * @hidden N
         * @exception
         * @example
         */
        function external_hover_img(data) {
            var hover_str = "_rov";
            for (var item in data) {
                var el = $(data[item].el).filter("[src*='" + data[item].src + "']");
                if (el.length > 0) {
                    var tmp = data[item].src.split("/");
                    var ext = /^.+\.([^.]+)$/.exec(tmp[1]);
                    var filename = tmp[1].replace("." + ext[1], "");
                    var rov_filename = filename + hover_str + "." + ext[1];
                    el.data("src-org", tmp[1]);
                    el.data("src-new", rov_filename);
                    el.hover(function() {
                        $(this).attr('src', $(this).attr('src').replace($(this).data("src-org"), $(this).data("src-new")));
                    }, function() {
                        $(this).attr('src', $(this).attr('src').replace($(this).data("src-new"), $(this).data("src-org")));
                    });
                }
            }
        };
        var default_hover_data = [{
            "el": "input",
            "src": "images/btn_login_main.png"
        }];
        /**
         * @method
         * @name menus_init
         * @description desc
         * @param
         * @returns
         * @hidden N
         * @exception
         * @example
         */
        function menus_init() {
            try {
                $('#gnb').children("li").each(function(i) {
                    $(this).children("a").bind("mouseover focus", function() {
                        $('#gnb li a.gma').removeClass("active");
                        $('div.lnb ul').removeClass("active");
                        $('div.lnb ul.lnb-' + i).addClass("active");
                    });
                });
                $('div.lnb ul li a').bind("mouseover focus", function() {
                    $('div.lnb ul li a').removeClass("active");
                    $(this).parent().parent().parent().parent().children("a.gma").addClass("active");
                });
                $('div#header').bind("mouseleave", function() {
                    $('#gnb li a.gma').removeClass("active");
                    $('div.lnb ul').removeClass("active");
                    if (dmenus.mmenu >= 0) {
                        $('#gnb').children("li").eq(dmenus.bmenu).children("a").addClass("active");
                        $('div.lnb ul.lnb-' + dmenus.bmenu).addClass("active");
                        if (dmenus.mmenu >= 0) {
                            $('div.lnb ul.lnb-' + dmenus.bmenu + " li").eq(dmenus.mmenu).children("a").addClass("active");
                        }
                    }
                });
                if (dmenus.bmenu >= 0) {
                    $('#gnb').children("li").eq(dmenus.bmenu).children("a").addClass("active");
                    $('div.lnb ul.lnb-' + dmenus.bmenu).addClass("active");
                    if (dmenus.mmenu >= 0) {
                        $('div.lnb ul.lnb-' + dmenus.bmenu + " li").eq(dmenus.mmenu).children("a").addClass("active");
                    }
                }
            } catch (e) {
                var tmp = 1;
            }
        };
        $(window).ready(function() {
            external_hover_img(default_hover_data);
            menus_init();
            $(window).scroll(function() {

            });
        });
    })(jQuery);
}
