//메뉴이동
/**
 * @method
 * @name goMenu
 * @description desc
 * @param {string} _menu desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.goMenu = function(_menu) {
    var _menu_id = $(_menu).attr('menu_id');
    var _now_time = $("#areaNowTimer").val();
    var _isur_cd = $("#areaIsurCd").val();

    //메뉴이동시 시간체크
