        return false;
    }
    var _uri = "/";
    if (_menu_id == "main") // 채권상장메인
        _uri = "/main/main.do";

    else if (_menu_id == "06") // WIT종목지정(국채)
        _uri = "/listeach/listeach.do?bnd_mktact_tp_cd=113&flag=NEW";

    else if (_menu_id == "00") // 개별신청(국채)
        _uri = "/listeach/listeach.do?bnd_mktact_tp_cd=111&flag=NEW";

    else if (_menu_id == "01") // 개별신청(지방채)
        _uri = "/listeach/listeach.do?bnd_mktact_tp_cd=121&flag=NEW";

    else if (_menu_id == "02") // 개별신청(특수채)
        _uri = "/listeach/listeach.do?bnd_mktact_tp_cd=131&flag=NEW";

    else if (_menu_id == "03") // 개별신청(회사채)
        _uri = "/listeach/listeach.do?bnd_mktact_tp_cd=141&flag=NEW";

    else if (_menu_id == "04") // 개별신청(외국채권)
        _uri = "/listeach/listeach.do?bnd_mktact_tp_cd=151&flag=NEW";

    else if (_menu_id == "05") // 개별신청(ELB/DLB)
        _uri = "/listeach/listeach.do?method=elbSearchNonListingBondList";

    else if (_menu_id == "10") // 일괄신청(국채)
        _uri = "/listbloc/blocListing.do?bnd_mktact_tp_cd=112&flag=NEW";

    else if (_menu_id == "11") // 일괄신청(지방채)
        _uri = "/listbloc/blocListing.do?bnd_mktact_tp_cd=122&flag=NEW";

    else if (_menu_id == "12") // 일괄신청(특수채)
        _uri = "/listbloc/blocListing.do?bnd_mktact_tp_cd=132&flag=NEW";

    else if (_menu_id == "13") // 일괄신청(지방공사채)
        _uri = "/listbloc/blocListing.do?bnd_mktact_tp_cd=142&flag=NEW&depthGubun=JIBANG";

    else if (_menu_id == "14") // 일괄신청(일괄상장금액조정)
        _uri = "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList&bnd_mktact_tp_cd=301";

    else if (_menu_id == "20") // 상호변경
        _uri = "/company/company.do?method=searchBndListByCoNmChg&bnd_mktact_tp_cd=201";

    else if (_menu_id == "21") // 합병/회사분할
        _uri = "/company/company.do?method=initMerge&bnd_mktact_tp_cd=202";

    else if (_menu_id == "22") // 종목분할
        _uri = "/company/company.do?method=initSplit&bnd_mktact_tp_cd=203";

    else if (_menu_id == "23") // 비분리형BW행사
        _uri = "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList&bnd_mktact_tp_cd=205";

    else if (_menu_id == "30") // 추가상장
        _uri = "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList&bnd_mktact_tp_cd=305";

    else if (_menu_id == "31") // 중도상환(부분)
        _uri = "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList&bnd_mktact_tp_cd=303";

    else if (_menu_id == "32") // 중도상환(전액)
        _uri = "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList&bnd_mktact_tp_cd=304";

    else if (_menu_id == "33") // 권리행사(주식관련사채)
        _uri = "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList&bnd_mktact_tp_cd=302";

    else if (_menu_id == "34") // 권리행사(일반사채)
        _uri = "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList&bnd_mktact_tp_cd=315";

    else if (_menu_id == "46") // WIT종목정보확정
