    else if (_menu_id == "42") // 발행가액
        _uri = "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList&bnd_mktact_tp_cd=307";

    else if (_menu_id == "43") // 권리행사가액
        _uri = "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList&bnd_mktact_tp_cd=306";

    else if (_menu_id == "44") // 상환일
