    else if (_menu_id == "50") // 스트립신규
        _uri = "/strip/strip.do?method=searchStripBndList&bnd_mktact_tp_cd=401";

    else if (_menu_id == "51") // 스트립추가 및 재결합
        _uri = "/strip/strip.do?method=searchStripBndList&bnd_mktact_tp_cd=402";

    else if (_menu_id == "52") // 원본채권별분리현황(조회)
        _uri = "/strip/strip.do?method=searchStripStateList";

    else if (_menu_id == "60") // 신청결과
        _uri = "/result/result.do";

    else if (_menu_id == "61") // 상장채권현황
        _uri = "/result/result.do?method=listingBondSearch";

    else if (_menu_id == "70") // 파일업로드
        _uri = "/upload/uploadFile.do";

    else if (_menu_id == "80") // 담당자정보변경
        _uri = "/account/userInfo.do?method=searchUserInfo";

    else if (_menu_id == "81") // 비밀번호변경
        _uri = "/account/userPw.do?method=updatePasswordForm&deal_div=2";

    else if (_menu_id == "90") // SRI채권등록
        _uri = "/sri/sribnd.do?method=showSriBndRegList";

    else if (_menu_id == "91") // 조달자금사용보고
        _uri = "/sri/sribnd.do?method=showSuplyFndUseRptList";
