//메뉴이동시 시간체크
/**
 * @method
 * @name menuTmCheck
 * @description desc
 * @param {string} _menu_id desc
 * @param {string} _now_time desc
 * @param {string} _isur_cd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.menuTmCheck = function(_menu_id, _now_time, _isur_cd) {
    //alert($("#bndApplPosblTmExcptYn").val());
    //alert("메뉴ID::"+_menu_id+",현재시간::"+_now_time+",발행기관코드::"+_isur_cd);

    var _excptYn = $("#bndApplPosblTmExcptYn").val(); //발행기관테이블에서 가져온 '채권신청가능시간예외여부'컬럼값
    if (_excptYn != null && _excptYn != '') {
        _excptYn = $("#bndApplPosblTmExcptYn").val();
    } else {
        _excptYn = 'N';
    }
    if (_menu_id == '' || _now_time == '' || _isur_cd == '') {
        //alert("잘못된 접근입니다.");
        return false;
    }

    //제한없음 -> 발행기관 : BND_APPL_POSBL_TM_EXCPT_YN 컬럼
    if (_excptYn == 'Y') {

    } else {
        //제한없음 -> 메뉴ID : 일괄상장, 스트립, 파일업로드, 계정관리
        if (_menu_id == '10' || _menu_id == '11' || _menu_id == '12' || _menu_id == '13' || _menu_id == '14' || _menu_id == '15' ||
            _menu_id == '60' || _menu_id == '61' || _menu_id == '70' || _menu_id == '80' || _menu_id == '81') {

        } else {
            //17시 제한 -> 메뉴ID : 신규상장, ELBDLB, WIT, SRI채권등록
            if (_menu_id == '01' || _menu_id == '02' || _menu_id == '03' || _menu_id == '04' || _menu_id == '05' || _menu_id == '06' || _menu_id == '90') {
                if (_now_time > "170000") {
                    alert("신청 가능 시간이 아닙니다.\n\n신청가능시간 : 9:00 ~ 17:00");
                    return false;
                }
            }
            //18시 제한 -> 메뉴ID : 상호변경/합병/분할, 상장금액변경, 종목정보변경, 조달자금사용보고
            else if (_menu_id == '20' || _menu_id == '21' || _menu_id == '22' || _menu_id == '23' || _menu_id == '91' ||
                _menu_id == '30' || _menu_id == '31' || _menu_id == '32' || _menu_id == '33' || _menu_id == '34' ||
                _menu_id == '40' || _menu_id == '41' || _menu_id == '42' || _menu_id == '43' || _menu_id == '44' || _menu_id == '45' || _menu_id == '46') {
                if (_now_time > "180000") {
                    alert("신청 가능 시간이 아닙니다.\n\n신청 가능시간 : 9:00 ~ 18:00");
                    return false;
                }
            }
        }
    }
    return true;
};


//신청버튼클릭시 시간체크
/**
 * @method
 * @name applTmCheck
 * @description desc
 * @param {string} _bnd_mktact_tp_cd desc
 * @param {string} _now_time desc
 * @param {string} _isur_cd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.applTmCheck = function(_bnd_mktact_tp_cd, _now_time, _isur_cd) {
    var _excptYn = $("#bndApplPosblTmExcptYn").val(); //발행기관테이블에서 가져온 '채권신청가능시간예외여부'컬럼값
    if (_excptYn != null && _excptYn != '') {
        _excptYn = $("#bndApplPosblTmExcptYn").val();
    } else {
        _excptYn = 'N';
    }
    var _temp = _bnd_mktact_tp_cd;
    if (_temp == '' || _now_time == '' || _isur_cd == '') {
        //alert("잘못된 접근입니다.");
        return false;
    }

    //제한없음 -> 발행기관 : BND_APPL_POSBL_TM_EXCPT_YN 컬럼
    if (_excptYn == 'Y') {

    } else {
        //17시 제한 -> 메뉴ID : 신규상장, ELBDLB, SRI채권등록
        if (_temp == '121' || _temp == '131' || _temp == '141' || _temp == '151' || _temp == 'SRI_REG') {
            if (_now_time > "170000") {
                alert("신청 가능 시간이 아닙니다.\n\n신청가능시간 : 9:00 ~ 17:00");
                return false;
            }
        }
        //18시 제한 -> 메뉴ID : 상호변경/합병/분할, 상장금액변경, 종목정보변경, 조달자금사용보고
        else if (_temp == '201' || _temp == '202' || _temp == '203' || _temp == '205' ||
            _temp == '302' || _temp == '303' || _temp == '304' || _temp == '315' ||
            _temp == '306' || _temp == '307' || _temp == '308' || _temp == '309' || _temp == '311' || _temp == '316' || _temp == '330' || _temp == 'SRI_RPT') {
            if (_now_time > "180000") {
                alert("신청 가능 시간이 아닙니다.\n\n신청 가능시간 : 9:00 ~ 18:00");
                return false;
            }
        }
    }
    return true;
};
